// Map form labels -> GHL option KEYS (GHL strips hyphens/spaces from keys).
const f = $input.first().json;
const key = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const TYPE_KEY = { 'SFR':'sfr', '2-4 Unit':'2to4unit', '5+ Unit':'5plusunit', 'Condo':'condo', 'Land':'land' };
const OCC_KEY = { 'VACANT AT CLOSE':'vacantatclose', 'Vacant Now':'vacantnow', 'Tenant Occupied':'tenantoccupied', 'Owner Occupied':'owneroccupied', 'Occupancy Unknown':'unknown' };
const num = (v) => (v === '' || v == null) ? undefined : Number(v);
const txt = (v) => (v == null ? '' : String(v).trim());

const address = txt(f['Address']);

// City and Zip are no longer separate inputs - derive them from the address so
// prop_city / prop_zip stay populated. Both are DISPLAY-ONLY (the teaser prompt
// and the GHL record); the match engine keys on County, which is still its own
// dropdown. A parse miss is cosmetic, never a mis-match.
const zipMatch = address.match(/\b(\d{5})(?:-\d{4})?\s*$/);
const derivedZip = zipMatch ? zipMatch[1] : '';
let derivedCity = '';
{
  // strip the trailing ", FL 33142" / " FL 33142"
  let head = address.replace(/[,\s]*\bFL\b[,\s]*\d{5}(?:-\d{4})?\s*$/i, '').trim();
  head = head.replace(/[,\s]+$/, '');
  if (head.indexOf(',') !== -1) {
    derivedCity = head.slice(head.lastIndexOf(',') + 1).trim();      // "123 St, Miami"
  } else if (head.indexOf('.') !== -1) {
    derivedCity = head.slice(head.lastIndexOf('.') + 1).trim();      // "2165 NW 58th St. Miami"
  }
  if (!derivedCity) {
    const w = head.split(/\s+/);
    derivedCity = w.length ? w[w.length - 1] : '';
  }
}

// Standard escrow unless the dispo manager overrides it.
const escrow = (!f['Escrow'] || Number(f['Escrow']) <= 0) ? 10000 : Number(f['Escrow']);

const props = {
  prop_address: address,
  prop_city: derivedCity,
  prop_zip: derivedZip,
  prop_county: key(f['County']),
  prop_type: TYPE_KEY[f['Property Type']],
  prop_headline: txt(f['Headline']),
  prop_occupancy: OCC_KEY[f['Occupancy']],
  prop_comps: txt(f['Comps']),
  prop_description: txt(f['Additional Details']),
  prop_dispo_status: 'intake',
};
const put = (k, v) => { if (v !== undefined && v !== '') props[k] = v; };
// prop_neighborhood is a fixed GHL picklist - an unrecognised value 400s the
// whole request, so validate and drop rather than fail the run.
const HOOD_KEYS = ["allapattah", "aventura", "balharbour", "bayharborislands", "belleglade", "bocaraton", "boyntonbeach", "brickell", "coconutcreek", "coconutgrove", "coopercity", "coralgables", "coralsprings", "coralway", "cutlerbay", "daniabeach", "davie", "deerfieldbeach", "delraybeach", "doral", "downtownmiami", "edgewater", "elportal", "floridacity", "fortlauderdale", "goldenglades", "greenacres", "hallandalebeach", "hialeah", "hialeahgardens", "hollywood", "homestead", "jupiter", "kendall", "keybiscayne", "lakeworthbeach", "lantana", "lauderdalelakes", "lauderhill", "libertycity", "lighthousepoint", "littlehaiti", "littlehavana", "loxahatchee", "margate", "miamibeach", "miamigardens", "miamilakes", "miamishores", "miamisprings", "miramar", "modelcity", "northbayvillage", "northlauderdale", "northmiami", "northmiamibeach", "oaklandpark", "opalocka", "other", "overtown", "palmbeachgardens", "palmettobay", "parkland", "pembrokepines", "perrine", "pinecrest", "plantation", "pompanobeach", "richmondheights", "rivierabeach", "royalpalmbeach", "southmiami", "sunnyislesbeach", "sunrise", "surfside", "sweetwater", "tamarac", "theroads", "uppereastside", "virginiagardens", "wellington", "westchester", "westmiami", "weston", "westpalmbeach", "wiltonmanors", "wynwood"];
const hoodKey = f['Neighborhood'] ? key(f['Neighborhood']) : '';
put('prop_neighborhood', HOOD_KEYS.indexOf(hoodKey) !== -1 ? hoodKey : undefined);
put('prop_beds', num(f['Beds']));
put('prop_baths', num(f['Baths']));
put('prop_sqft', num(f['Living Area Sqft']));
put('prop_lot_sqft', num(f['Lot Size Sqft']));
put('prop_year_built', num(f['Year Built']));
put('prop_roof_age', txt(f['Roof Age']));
put('prop_ac_age', txt(f['AC Age']));
put('prop_key_upgrades', txt(f['Key Upgrades']));
put('prop_hoa', txt(f['HOA']));
put('prop_liens_violations', txt(f['Liens or Violations']));
put('prop_highlights', txt(f['Extra Highlights']));
put('prop_asking_price', num(f['Asking Price']));
put('prop_arv', num(f['ARV']));
put('prop_repair_est', num(f['Repair Estimate']));
put('prop_emd_terms', '$' + escrow.toLocaleString('en-US'));
put('prop_photos_url', txt(f['Photos Videos URL']));
put('prop_close_date', txt(f['Close Date']));
put('prop_access_notes', txt(f['Access Notes']));

// MAO deliberately NOT computed — settled during acquisition.

return [{ json: { props, address, searchQuery: address, escrow, derivedCity, derivedZip, raw: f } }];

// prop_address is UNIQUE in GHL. A blind create fails once the acquisition
// side has already filed the house, so decide create vs update here.
const search = $input.first().json;
const intake = $('Normalize + Map Keys').first().json;
const norm = (s) => (s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const target = norm(intake.address);
const hit = (search.records || []).find(r => norm(r.properties?.prop_address) === target);
return [{ json: { ...intake, exists: !!hit, recordId: hit ? hit.id : null } }];

// ============================================================
// EXCLUSION ENGINE — default is INCLUDE.
//
// Extracted buy_* data is a GUESS (parsed from old prose notes, never
// confirmed with the buyer). It is NEVER used to filter a blast. Using it to
// filter means a buyer whose 2024 note said "Broward only" silently stops
// hearing about Dade deals and nobody ever finds out.
//
// A buyer drops out of a blast ONLY when a human set an excl_* rule after
// actually talking to them.
//
// The buy_* data still earns its keep: where it CONTRADICTS the deal but no
// excl_* rule exists, it produces a review suggestion — an interview queue.
// ============================================================
const pages = $input.all();
const pool = pages.flatMap(p => p.json.contacts || []);

const deal = $('Create or Update?').first().json;
const p = deal.props, f = deal.raw;

// GHL returns a contact's customFields as [{id, value}] with NO field name,
// so look the id up from the definitions first. Without this every lookup
// returns null and no excl_ rule can ever fire - a silent, invisible failure.
const defs = ($('Fetch Field Definitions').first().json.customFields) || [];
const ID_BY_NAME = {};
for (const d of defs) ID_BY_NAME[d.name] = d.id;

const cf = (c, name) => {
  const id = ID_BY_NAME[name];
  const hit = (c.customFields || []).find(x => x.id === id || x.id === name || x.key === name);
  if (!hit) return null;
  return hit.value !== undefined ? hit.value : (hit.fieldValue !== undefined ? hit.fieldValue : null);
};
const arr = (v) => v == null ? [] : (Array.isArray(v) ? v : String(v).split(';').map(s => s.trim()).filter(Boolean));
const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const n = (v) => (v == null || v === '') ? null : Number(v);


// Address comparison for deal-scoping. Tolerant of "2165 NW 58th St" vs
// "2165 NW 58th St. Miami, FL 33142" - either containing the other counts.
const normAddr = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const addrMatch = (a, b) => {
  if (!a || !b) return false;
  return a === b || a.indexOf(b) !== -1 || b.indexOf(a) !== -1;
};
const dealAddr = normAddr(p.prop_address);
const dealCounty = norm(f['County']);
const dealHood   = norm(f['Neighborhood'] || '');
const dealType   = norm(f['Property Type']);
const asking = n(p.prop_asking_price);
const sqft   = n(p.prop_sqft);

const included = [], excluded = [], suppressed = [], suggestions = [];
let notBuyers = 0;

for (const c of pool) {
  const name = [c.firstName, c.lastName].filter(Boolean).join(' ') || c.contactName || '(no name)';
  const tier = cf(c, 'buy_tier') || '(none)';
  const srcList = arr(cf(c, 'buy_source'));
  const src = srcList.length ? srcList.join(', ') : '(none)';
  // Recency answers the real question: did the InvestorBase import for
  // THIS deal actually finish before the form was submitted?
  const addedMs = c.dateAdded ? Date.parse(c.dateAdded) : 0;
  const freshlyAdded = addedMs > 0 && (Date.now() - addedMs) < 2 * 60 * 60 * 1000;
  const row = { id: c.id, name, phone: c.phone || null, tier, source: src, freshlyAdded, segment: '' };

  // ---- HARD SUPPRESSIONS: not preferences. Compliance and physics. ----
  // record_type must positively say Buyer. A blank record_type is NOT an
  // implicit buyer - seller leads, inbound web contacts and CRM demo records
  // all arrive with it empty, and none of them should get a wholesale blast.
  // This is a classification check, not a preference, so it is not subject to
  // the exclusion-by-default rule.
  const rt = arr(cf(c, 'record_type')).map(norm);
  if (!rt.includes('buyer')) { notBuyers++; continue; }

  const status = norm(cf(c, 'buy_status'));
  if (status === 'dnc' || status === 'blacklist') {
    suppressed.push({ ...row, why: 'buy_status=' + status });
    continue;
  }
  if (!c.phone) { suppressed.push({ ...row, why: 'no phone on file' }); continue; }

  // ---- EXCLUSION RULES: the only thing that removes a buyer ----
  const why = [];

  if (norm(cf(c, 'excl_all_blasts')) === 'yes') why.push('held from all blasts');

  // ---- InvestorBase buyers are DEAL-SCOPED ----
  // IB returns buyers within ~2 miles of one subject property. They were never
  // a general buyer list, so they are only eligible for the deal they were
  // pulled for. Master-list buyers (BH Main / Referral) get everything.
  const srcNorm = arr(cf(c, 'buy_source')).map(norm);
  // SEGMENT, do not exclude. Source decides the SCRIPT, not eligibility.
  // An InvestorBase buyer sourced for another property is still a real cash
  // buyer in this county - excluding them would throw away the database the
  // imports exist to build.
  const pulledLines = String(cf(c, 'buy_ib_property') || '')
    .split('
').map(s => normAddr(s)).filter(Boolean);
  const geoMatched = pulledLines.some(a => addrMatch(a, dealAddr));
  const inquiredHere = srcNorm.includes('investorlift') && geoMatched;

  let segment;
  if (inquiredHere) segment = 'inquired';
  else if (srcNorm.includes('bhmain') || srcNorm.includes('referral')) segment = 'warm';
  else if (geoMatched) segment = 'geo_cold';
  else segment = 'general_cold';


  const belowPrice = n(cf(c, 'excl_below_price'));
  if (belowPrice && asking && asking < belowPrice)
    why.push('asking ' + asking + ' below their floor ' + belowPrice);

  const abovePrice = n(cf(c, 'excl_above_price'));
  if (abovePrice && asking && asking > abovePrice)
    why.push('asking ' + asking + ' above their ceiling ' + abovePrice);

  const belowSqft = n(cf(c, 'excl_below_sqft'));
  if (belowSqft && sqft && sqft < belowSqft)
    why.push('sqft ' + sqft + ' below their floor ' + belowSqft);

  const exTypes = arr(cf(c, 'excl_prop_types')).map(norm);
  if (exTypes.length && dealType && exTypes.includes(dealType))
    why.push('excludes ' + f['Property Type']);

  const onlyCounties = arr(cf(c, 'excl_outside_counties')).map(norm);
  if (onlyCounties.length && dealCounty && !onlyCounties.includes(dealCounty))
    why.push('outside their counties');

  const onlyHoods = arr(cf(c, 'excl_outside_neighborhoods')).map(norm);
  if (onlyHoods.length && dealHood && !onlyHoods.includes(dealHood))
    why.push('outside their sub-markets');

  if (why.length) {
    excluded.push({ ...row, why: why.join('; '),
                    note: cf(c, 'excl_notes') || '', verified: cf(c, 'excl_verified_date') || '' });
    continue;
  }

  // ---- INCLUDED. Now: does unverified buy_* data hint at a missing rule? ----
  const hints = [];
  const bCounties = arr(cf(c, 'buy_counties')).map(norm);
  if (!onlyCounties.length && bCounties.length && dealCounty && !bCounties.includes(dealCounty))
    hints.push('notes say ' + arr(cf(c, 'buy_counties')).join('/') + ' only');

  const bHoods = arr(cf(c, 'buy_neighborhoods'));
  if (!onlyHoods.length && bHoods.length && dealHood && !bHoods.map(norm).includes(dealHood))
    hints.push('notes say ' + bHoods.join('/') + ' only');

  const bMin = n(cf(c, 'buy_price_min'));
  if (!belowPrice && bMin && asking && asking < bMin) hints.push('notes say min ' + bMin);

  const bMax = n(cf(c, 'buy_price_max'));
  if (!abovePrice && bMax && asking && asking > bMax) hints.push('notes say max ' + bMax);

  const bSqft = n(cf(c, 'buy_sqft_min'));
  if (!belowSqft && bSqft && sqft && sqft < bSqft) hints.push('notes say min ' + bSqft + ' sqft');

  const bTypes = arr(cf(c, 'buy_prop_types'));
  if (!exTypes.length && bTypes.length && dealType && !bTypes.map(norm).includes(dealType))
    hints.push('notes say ' + bTypes.join('/') + ' only');

  row.segment = segment;
  included.push(row);
  if (hints.length) suggestions.push({ ...row, hint: hints.join('; '),
                                       action: 'CONFIRM WITH BUYER, then set an excl_ rule if true' });
}

const rank = { VIP: 0, A: 1, B: 2, C: 3 };
included.sort((a, b) => (rank[a.tier] ?? 9) - (rank[b.tier] ?? 9));

return [{ json: {
  recordId: deal.recordId,
  created: !deal.exists,
  props: p,
  raw: f,
  pagesFetched: pages.length,
  poolSize: pool.length,
  notBuyers,
  fieldDefsLoaded: Object.keys(ID_BY_NAME).length,
  includedCount: included.length,
  bySegment: (function () {
    const m = { inquired: 0, warm: 0, geo_cold: 0, general_cold: 0 };
    for (const b of included) if (b.segment) m[b.segment] = (m[b.segment] || 0) + 1;
    return m;
  })(),
  bySource: (function () {
    const m = {};
    for (const b of included) m[b.source] = (m[b.source] || 0) + 1;
    return m;
  })(),
  freshlyAddedCount: included.filter(b => b.freshlyAdded).length,
  excludedCount: excluded.length,
  suppressedCount: suppressed.length,
  included,
  excluded,
  suppressed,
  suggestions,
} }];

// Build the WhatsApp post DETERMINISTICALLY. No LLM touches these numbers:
// prices, comps and sqft render straight from the form, so they cannot be
// paraphrased, rounded, or invented.
const d = $input.first().json;
const p = d.props, f = d.raw;

const money = (n) => '$' + Number(n).toLocaleString('en-US');
const nf = (n) => Number(n).toLocaleString('en-US');
// Strip any bullet the user typed themselves - the template adds its own.
const lines = (s) => (s || '').split('\n').map(x => x.trim().replace(/^[-\u2022*\u00B7\u2013\u2014]+\s*/, '')).filter(Boolean);
const T = (v) => (v == null ? '' : String(v).trim());

const fullAddress = T(f['Address']).replace(/[,\s]+$/, '');
// Computed here, not read from upstream - the exclusion engine does not
// pass it through, which rendered 'Escrow: $NaN'.
const escrow = (!f['Escrow'] || Number(f['Escrow']) <= 0) ? 10000 : Number(f['Escrow']);
// 'unknown' typed into an age field should read as unknown, not 'is unknown'.
const UNK = (v) => /^(unknown|unk|n\/a|na|\?)$/i.test(T(v));

// ---- Details bullets, in the house order ----
const details = [];
details.push('Beds/Bath: ' + T(f['Beds']) + '/' + T(f['Baths']));
details.push('Living Area: ' + nf(f['Living Area Sqft']) + ' sq ft');
if (f['Lot Size Sqft']) details.push('Lot Size: ' + nf(f['Lot Size Sqft']) + ' sq ft');
details.push((T(f['Roof Age']) && !UNK(f['Roof Age'])) ? 'Roof is ' + T(f['Roof Age']) : 'Roof age unknown');
if (T(f['Key Upgrades'])) details.push('Key Upgrades - ' + T(f['Key Upgrades']));
details.push((T(f['AC Age']) && !UNK(f['AC Age'])) ? 'AC is ' + T(f['AC Age']) : 'AC age unknown');
for (const h of lines(f['Extra Highlights'])) details.push(h);
if (T(f['HOA'])) details.push(T(f['HOA']));
if (T(f['Liens or Violations'])) details.push(T(f['Liens or Violations']));

const occupancy = T(f['Occupancy']);
const comps = lines(f['Comps']);

// ---- WhatsApp (single asterisks render as bold) ----
const wa = [];
wa.push('\uD83C\uDFE0 *' + fullAddress + '*');
wa.push('');
wa.push('\u2B50' + T(f['Headline']));
wa.push('');
wa.push('\uD83D\uDFE0 *Details*');
for (const b of details) wa.push(' \u00B7 ' + b);
if (occupancy) wa.push(' \u00B7 *' + occupancy + '*');
wa.push('');
wa.push('\uD83D\uDFE0 *Comps*');
for (const c of comps) wa.push(' \u00B7 ' + c);
wa.push('');
wa.push('\uD83D\uDCB0 *Price:* Only ' + money(f['Asking Price']));
wa.push('');
wa.push('\uD83D\uDCC8 *ARV:* ~' + money(f['ARV']));
wa.push('');
wa.push('\uD83D\uDCF8 *Photos/Videos:*');
wa.push(T(f['Photos Videos URL']));
wa.push('\uD83D\uDCB5 *Escrow:* ' + money(escrow));
const whatsapp_post = wa.join('\n');

// ---- SMS: identical content, asterisks stripped.
// SMS has no bold — leaving them in shows literal * to the buyer.
const sms_post = whatsapp_post.replace(/\*/g, '');

return [{ json: Object.assign({}, d, { fullAddress, whatsapp_post, sms_post }) }];

const res = $input.first().json;
const d = $('Build WhatsApp + SMS Post').first().json;

// Only one of Create/Update ran, so probe both. Referencing a node that did
// not execute throws, hence the try/catch rather than an if.
let recId = d.recordId || null;
if (!recId) { try { const r = $('Create Property').first().json; recId = (r.record && r.record.id) || r.id || null; } catch (e) {} }
if (!recId) { try { const r = $('Update Property').first().json; recId = (r.record && r.record.id) || r.id || null; } catch (e) {} }

let ai = {}, aiError = null;
try {
  const t = (res.content || []).find(b => b.type === 'text');
  ai = JSON.parse(t.text);
} catch (e) { aiError = String(e); }

return [{ json: {
  status: 'DRAFTS READY - NOTHING SENT',
  property_record_id: recId,
  property_action: d.created ? 'CREATED' : 'UPDATED existing record',
  address: d.fullAddress,
  buyers_included: d.includedCount,
  by_source: d.bySource,
  by_segment: d.bySegment,
  imported_last_2h: d.freshlyAddedCount,
  buyers_excluded: d.excludedCount,
  buyers_suppressed: d.suppressedCount,
  buyers_scanned: d.poolSize,
  not_buyers_skipped: d.notBuyers,
  pages_fetched: d.pagesFetched,
  whatsapp_post: d.whatsapp_post,
  sms_post: d.sms_post,
  teaser_sms: ai.teaser_sms || null,
  hook_used: ai.hook_used || null,
  email_subject: ai.email_subject || null,
  voice_brief: ai.voice_brief || null,
  ai_error: aiError,
  included: d.included,
  excluded: d.excluded,
  suppressed: d.suppressed,
  review_suggestions: d.suggestions
} }];

// Build the Anthropic request as a real object. n8n's expression parser
// rejects a body this large inline ("invalid syntax"), so it lives here.
const d = $input.first().json;
const f = d.raw;

const SYSTEM = [
  'You write short outreach texts for Buying Hero, a South Florida wholesaler, to its cash-buyer list.',
  'Non-negotiable rules:',
  '(1) The teaser NEVER contains the street address - withholding it is what forces the reply. City is fine.',
  '(2) Never invent exclusivity, urgency, competing offers, deadlines, or any claim you were not given.',
  '(3) Never state a number you were not given.',
  '(4) Sound like a person texting a contact they know. Short sentences, no emoji, no ALL CAPS, no marketing voice.'
].join(' ');

const facts = [
  'City: ' + (d.derivedCity || f['City'] || ''),
  'Beds/Baths: ' + f['Beds'] + '/' + f['Baths'],
  'Type: ' + f['Property Type'],
  'ARV: ' + f['ARV'],
  'Asking: ' + f['Asking Price'],
  'Headline feature: ' + f['Headline'],
  '',
  'Additional details from the dispo manager:',
  (f['Additional Details'] || '(none provided - work from the facts above)'),
  '',
  'Write the teaser set.'
].join('\n');

const claudeBody = {
  model: 'claude-opus-5',
  max_tokens: 8000,
  system: SYSTEM,
  messages: [{ role: 'user', content: facts }],
  output_config: {
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          teaser_sms:    { type: 'string', description: 'Under 320 characters. Beds/baths, city, ARV, price, one standout feature, soft CTA. NO street address. Use {{first_name}} for the buyer and Andrew as sender.' },
          hook_used:     { type: 'string', description: 'The opener line only, so it can be written to buy_last_hook and never reused on the same buyer.' },
          email_subject: { type: 'string', description: 'Subject line for the email version.' },
          voice_brief:   { type: 'string', description: 'Plain fact sheet the voice AI answers from. Facts only, no script, no persuasion.' }
        },
        required: ['teaser_sms', 'hook_used', 'email_subject', 'voice_brief'],
        additionalProperties: false
      }
    }
  }
};

return [{ json: Object.assign({}, d, { claudeBody }) }];

